const r2 = (v) => Math.round(v * 100) / 100;

// Half-width profile of the 28 fl oz bottle below the neck: [y, half width], measured from the tile.
const PROFILE = [
  [34.6, 19.6], [43.7, 20.3], [47, 22.6], [50.5, 26], [54.5, 30.4], [58.5, 34.8], [62.5, 38.8], [66.5, 41.9],
  [70.5, 44.3], [74.5, 45.8], [79, 46.1], [100, 45.6], [121, 45.6], [125.5, 44], [129.5, 40], [133, 40.6],
  [137.5, 42.2], [142, 41.2], [147, 38.3], [152, 38], [157, 39.6], [162, 42], [170, 42.6], [180, 42.4],
  [185, 40.6], [189.5, 39], [194, 39.8], [199, 42], [205, 44], [210, 44.1], [214, 42.6], [218.5, 44.2],
  [224, 45.4], [228.5, 44.8], [232, 42.2], [234.6, 37],
];

// Catmull-Rom through the points, written as cubic segments.
function spline(pts) {
  let d = '';
  for (let i = 0; i < pts.length - 1; i++) {
    const p0 = pts[Math.max(0, i - 1)], p1 = pts[i], p2 = pts[i + 1], p3 = pts[Math.min(pts.length - 1, i + 2)];
    const c1 = [p1[0] + (p2[0] - p0[0]) / 6, p1[1] + (p2[1] - p0[1]) / 6];
    const c2 = [p2[0] - (p3[0] - p1[0]) / 6, p2[1] - (p3[1] - p1[1]) / 6];
    d += `C${r2(c1[0])} ${r2(c1[1])} ${r2(c2[0])} ${r2(c2[1])} ${r2(p2[0])} ${r2(p2[1])}`;
  }
  return d;
}

const LEFT = PROFILE.map(([y, h]) => [100 - h, y]);
const RIGHT = PROFILE.map(([y, h]) => [100 + h, y]).reverse();
// Petaloid base: five shallow feet between the two outer corners.
const FEET = 'Q65 236.4 71 235.8Q77 231.6 82 235.4Q90 236.8 98 235.4Q100 232.8 102 235.4Q110 236.8 118 235.4Q123 231.6 129 235.8Q135 236.4';
const BODY = `M${LEFT[0][0]} ${LEFT[0][1]}${spline(LEFT)}${FEET} ${RIGHT[0][0]} ${RIGHT[0][1]}${spline(RIGHT)}Z`;

// Hex grip: a honeycomb of wide, flat-topped cells (pointed at the sides; the centre column offset
// half a pitch from the side columns), drawn as soft translucent planes: light upper half, dark lower half.
function hex(cx, cy) {
  const w = 29, f = 12, h = 17;
  const P = (...q) => 'M' + q.map((p) => `${r2(p[0])} ${r2(p[1])}`).join('L') + 'Z';
  const d = P([cx - w, cy], [cx - f, cy - h], [cx + f, cy - h], [cx + w, cy], [cx + f, cy + h], [cx - f, cy + h]);
  return `<path d="${d}" fill="${ref('dimple')}"/>`
    + `<path d="${d}" fill="none" stroke="#fff" stroke-opacity=".13" stroke-width=".9" stroke-linejoin="round"/>`;
}
function grip() {
  let s = '';
  for (const cy of [122, 156, 190, 224]) s += hex(59, cy) + hex(141, cy);
  for (const cy of [139, 173, 207, 241]) s += hex(100, cy);
  return `<g clip-path="${ref('gripclip')}">${s}</g>`;
}

